JS = r'''
const directions=__DIRECTIONS__;
let activeStyle='editorial',activeView='results';
const styleButtons=[...document.querySelectorAll('[data-style]')];
function applyStyle(style){
  if(!directions[style])return;
  activeStyle=style;
  document.querySelectorAll('[data-candidate]').forEach(panel=>panel.hidden=panel.dataset.candidate!==style);
  styleButtons.forEach(button=>{const selected=button.dataset.style===style;button.setAttribute('aria-selected',String(selected));button.tabIndex=selected?0:-1});
  document.getElementById('direction-title').textContent=directions[style][1]+' — '+directions[style][2];
  document.getElementById('direction-copy').textContent=directions[style][3];
}
function applyView(view){
  if(!['results','transcript'].includes(view))return;
  activeView=view;
  document.querySelectorAll('[data-screen]').forEach(screen=>screen.hidden=screen.dataset.screen!==view);
  document.querySelectorAll('.view-choice').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.view===view)));
}
styleButtons.forEach((button,index)=>{
  button.addEventListener('click',()=>applyStyle(button.dataset.style));
  button.addEventListener('keydown',event=>{let next;if(event.key==='ArrowRight')next=(index+1)%3;else if(event.key==='ArrowLeft')next=(index+2)%3;else if(event.key==='Home')next=0;else if(event.key==='End')next=2;else return;event.preventDefault();styleButtons[next].focus();applyStyle(styleButtons[next].dataset.style)});
});
document.querySelectorAll('[data-view]').forEach(button=>button.addEventListener('click',()=>{applyView(button.dataset.view);if(!button.classList.contains('view-choice'))window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}));
let toastTimer;
function toast(message){const node=document.getElementById('toast');clearTimeout(toastTimer);node.textContent=message;node.hidden=false;toastTimer=setTimeout(()=>node.hidden=true,6500)}
document.querySelectorAll('[data-action]').forEach(button=>button.addEventListener('click',()=>{
  if(button.dataset.action==='print'){window.print();return;}
  toast(button.dataset.action==='generate'?'This file previews the design. The live app generates a fresh 45–55 minute example through OpenAI.':'This preview runs offline. It makes no network requests, saves no meeting content and uses only the bundled fictional sample.');
}));
const params=new URLSearchParams(location.search);applyStyle(params.get('style')||activeStyle);applyView(params.get('view')||activeView);
window.addEventListener('pagehide',()=>clearTimeout(toastTimer));
'''.replace('__DIRECTIONS__', json.dumps(styles))

buttons = ''.join(f'<button class="style-choice" role="tab" id="tab-{key}" aria-controls="candidate-{key}" aria-selected="{"true" if key == "editorial" else "false"}" tabindex="{0 if key == "editorial" else -1}" data-style="{key}"><span class="swatch" aria-hidden="true"></span>{value[1]}</button>' for key, value in styles.items())
notices = ''.join(f'<h3>{escape(slug)}</h3><pre>{escape(licence)}</pre>' for slug, licence in licences)
html = f'''<!doctype html><html lang="en-GB"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Meeting Coach — three design directions</title><style>{font_css}{CSS}</style></head><body>
<div class="comparison-bar"><div class="comparison-title">Meeting Coach / Design directions<span>Same content. Three ways to present it.</span></div><div class="choices" role="tablist" aria-label="Design style">{buttons}</div><div class="views" aria-label="Preview screen"><button class="view-choice" data-view="results" aria-pressed="true">Results</button><button class="view-choice" data-view="transcript" aria-pressed="false">Transcript</button></div></div>
<div class="direction-note"><strong id="direction-title">Editorial — A report you want to read.</strong><p id="direction-copy">{styles['editorial'][3]}</p></div>
{''.join(panels)}<div id="toast" class="toast" role="status" aria-live="polite" hidden></div><details class="font-notices"><summary>Font licences · self-contained offline preview</summary>{notices}</details><script>{JS}</script></body></html>'''
path = OUT / 'meeting-coach-style-options.html'
path.write_text(html)
print(f'{path}: {len(html.encode()):,} bytes; 3 styles × 2 screens, 7 categories / 24 criteria per style; embedded fonts; no external requests.')

# Owner's chosen direction: Calm layout with Editorial colour and typography.
combined_css = '''
.choices,.direction-note{display:none!important}
[data-candidate=calm]{--color-paper:#f7f3eb;--color-surface:#fcfaf5;--color-ink:#332a2b;--color-muted:#6f5d59;--color-accent:#6c253e;--color-accent-ink:#fcfaf5;--color-accent-soft:#eee2df;--color-rule:#d8ccc3;--color-boundary:#93877c;--color-focus:#6c253e;--font-display:'Fraunces',serif;--font-body:'IBM Plex Sans',sans-serif;--font-label:'IBM Plex Sans',sans-serif}
[data-candidate=calm] h1,[data-candidate=calm] h2,[data-candidate=calm] .brand{font-weight:400}
[data-candidate=calm] .brand{font-size:29px}
[data-candidate=calm] h1{font-size:clamp(32px,3.8vw,46px);letter-spacing:-1px}
[data-candidate=calm] h2{font-size:30px;letter-spacing:-.5px}
[data-candidate=calm] .big-score{font-weight:400;font-size:70px}
@media(max-width:520px){[data-candidate=calm] .brand{font-size:25px}[data-candidate=calm] h1{font-size:32px}[data-candidate=calm] h2{font-size:26px}}
'''
combined = html.replace('</style>', combined_css + '</style>').replace("activeStyle='editorial'", "activeStyle='calm'").replace('A little better, next meeting.', 'Your meeting review').replace('Meeting Coach / Design directions', 'Meeting Coach / Chosen direction').replace('Same content. Three ways to present it.', 'Calm layout · Editorial colour and type').replace('Meeting Coach — three design directions', 'Meeting Coach — Calm layout, Editorial style')
combined_path = OUT / 'meeting-coach-combined-style.html'
combined_path.write_text(combined)
print(f'{combined_path}: selected combination, both screens and all original scoring content.')
